/// Merge another path router into this one, but when a path already exists in `self`,
/// either replace it or skip it depending on `replace_on_conflict`.
pub(super) fn merge_fallback(
    &mut self,
    other: PathRouter<S, IS_FALLBACK>,
    replace_on_conflict: bool,
) -> Result<(), Cow<'static, str>> {
    let PathRouter {
        routes,
        node,
        prev_route_id: _,
    } = other;

    for (id, route) in routes {
        let path = node
            .route_id_to_path
            .get(&id)
            .expect("no path for route id. This is a bug in axum. Please file an issue");

        if self.node.path_to_route_id.contains_key(path.as_ref()) {
            if replace_on_conflict {
                let endpoint = match route {
                    Endpoint::MethodRouter(_) => route,
                    Endpoint::Route(route) => Endpoint::Route(route),
                };
                self.replace_endpoint(path, endpoint);
            }
            // else: skip, keep self's version
        } else {
            match route {
                Endpoint::MethodRouter(method_router) => self.route(path, method_router)?,
                Endpoint::Route(route) => self.route_service(path, route)?,
            };
        }
    }

    Ok(())
}

